  id: '1',
  name: 'Alice',
  email: 'alice@example.com',
  role: 'admin'
};

// File: next-auth.d.ts
declare module 'next-auth' {
  interface Session {
    user: {
      id: string;
      name?: string;
      email?: string;
      image?: string;
      role: 'admin' | 'member';
    };
  }

  interface User {
    id: string;
    role: 'admin' | 'member';
  }
}

// Now session.user.role is known to TypeScript
export default NextAuth({
  providers: [GoogleProvider],
  callbacks: {
    session({ session, token }) {
      session.user.role = token.role;
      return session;
    }
  }
});

